import { FocusMonitor } from '@angular/cdk/a11y';
import {
  Directive,
  DoCheck,
  ElementRef,
  HostBinding,
  Injector,
  Input,
  OnDestroy,
  OnInit,
  booleanAttribute,
  inject,
} from '@angular/core';
import { FormGroupDirective, NgControl, NgForm, NgModel } from '@angular/forms';
import { ErrorState } from '@questrade/allspark-angular-components/core/utils';
import {
  ErrorStateMatcher,
  ErrorStateMatcherInterface,
  FormFieldControl,
} from '@questrade/allspark-angular-components/form-control';

let nextUniqueId = 0;

@Directive({
  selector: 'input[qInput]',
  providers: [{ provide: FormFieldControl, useExisting: QInputDirective }],
})
export class QInputDirective
  extends ErrorState
  implements OnInit, FormFieldControl, DoCheck, OnDestroy
{
  @Input() override errorStateMatcher: ErrorStateMatcherInterface = new ErrorStateMatcher();
  @Input({ transform: booleanAttribute }) invalidState = false;
  @Input() @HostBinding('attr.id') controlId = `q-input-${nextUniqueId++}`;
  @Input() @HostBinding('attr.data-qt') dataQt = 'q-input';

  @HostBinding('class') get hostClasses(): string {
    return ['q-input', this.invalidState && 'q-input-invalid'].filter(Boolean).join(' ');
  }

  private readonly _focusMonitor = inject(FocusMonitor);
  private readonly _elementRef = inject(ElementRef);
  private readonly _injector = inject(Injector);

  constructor() {
    super(inject(FormGroupDirective, { optional: true }), inject(NgForm, { optional: true }));
  }

  ngOnInit(): void {
    this._setComponentControl();

    this._focusMonitor.monitor(this._elementRef);
  }

  ngDoCheck(): void {
    if (this.ngControl) {
      this._updateErrorState();

      if (!(this.ngControl instanceof NgModel)) {
        this.invalidState = this.errorState;
      }
    }
  }

  ngOnDestroy(): void {
    this._focusMonitor.stopMonitoring(this._elementRef);
  }

  private _setComponentControl(): void {
    const injectedControl = this._injector.get(NgControl, null);

    if (injectedControl) {
      this.ngControl = injectedControl;
    }
  }
}
