import { FocusMonitor } from '@angular/cdk/a11y';
import { NgIf, NgTemplateOutlet } from '@angular/common';
import {
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Component,
  ElementRef,
  HostBinding,
  Input,
  OnInit,
  TemplateRef,
  ViewEncapsulation,
  inject,
} from '@angular/core';
import { QDestroyService } from '@questrade/allspark-angular-components/core/services';
import { takeUntil } from 'rxjs';

@Component({
  imports: [NgIf, NgTemplateOutlet],
  providers: [QDestroyService],
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
  selector: 'q-input-group',
  template: `
    <span *ngIf="prefix" #prefixTemplate class="q-input-group-prefix">
      <ng-container *ngTemplateOutlet="prefix" />
    </span>

    <ng-content />

    <span *ngIf="suffix" #suffixTemplate class="q-input-group-suffix">
      <ng-container *ngTemplateOutlet="suffix" />
    </span>
  `,
  styleUrls: ['./input-group.component.scss'],
})
export class QInputGroupComponent implements OnInit {
  @Input() prefix: TemplateRef<HTMLElement> | null = null;
  @Input() suffix: TemplateRef<HTMLElement> | null = null;
  @Input() @HostBinding('attr.data-qt') dataQt = 'q-input-group';

  @HostBinding('class') get hostClasses(): string {
    return ['q-input-group', this._focused && 'q-input-group-focused', 'q-focus-indicator']
      .filter(Boolean)
      .join(' ');
  }

  private readonly _focusMonitor = inject(FocusMonitor);
  private readonly _elementRef = inject(ElementRef);
  private readonly _destroy$ = inject(QDestroyService);
  private readonly _cdr = inject(ChangeDetectorRef);
  private _focused = false;

  ngOnInit(): void {
    this._focusMonitor
      .monitor(this._elementRef, true)
      .pipe(takeUntil(this._destroy$))
      .subscribe((focusOrigin) => {
        this._focused = !!focusOrigin;
        this._cdr.markForCheck();
      });
  }
}
